"""Shared quest/slice transition predicates for v2 runner and manual advance."""

from __future__ import annotations

from pathlib import Path

from .. import quest_fs
from ..quest_runner import (
    all_required_slice_plan_files_exist,
    current_project_rel_for_quest,
    docs_updated_for_quest,
    implementer_done_signal,
    implementation_review_done_signal,
    physical_plan_review_done_signal,
    quest_has_open_physicalplan_issues,
    slice_has_open_polishing_issues,
)
from ..quest_types import QuestMeta, SliceState


class AdvanceValidationError(Exception):
    """Manual advance blocked by unmet predicates; state must not change."""

    def __init__(self, message: str, *, reason: str) -> None:
        self.message = message
        self.reason = reason
        super().__init__(message)


def physical_planning_next_state(quest_dir: Path) -> str:
    slice_dirs = quest_fs.list_slice_dirs(quest_dir)
    if slice_dirs and all_required_slice_plan_files_exist(quest_dir):
        return "ReviewPhysicalPlan"
    raise AdvanceValidationError(
        "Physical planning is incomplete: slice directories and required "
        "physicalplan/state files are missing.",
        reason="incomplete_physical_plan",
    )


def review_physical_plan_next_state(quest_dir: Path) -> str:
    if quest_has_open_physicalplan_issues(quest_dir):
        return "PhysicalPlanning"
    if physical_plan_review_done_signal(quest_dir):
        return "PrepareNextSlice"
    raise AdvanceValidationError(
        "Physical plan review is incomplete: resolve open issues and create "
        "`physicalplan_accepted.md` before advancing.",
        reason="physical_plan_review_incomplete",
    )


def prepare_next_slice_transition(quest_dir: Path) -> tuple[str, dict[str, str]]:
    dirs = quest_fs.list_slice_dirs(quest_dir)
    unfinished = [
        d
        for d in dirs
        if quest_fs.read_slice_state(d).state != SliceState.Done
    ]
    if not unfinished:
        return "QuestDocumenting", {}
    top = quest_fs.read_quest_state(quest_dir)
    cur = top.active_slice
    order = [d.name for d in dirs]
    if not cur:
        return "ExecuteSlice", {"active_slice": unfinished[0].name}
    try:
        i = order.index(cur)
    except ValueError:
        return "ExecuteSlice", {"active_slice": unfinished[0].name}
    for d in unfinished:
        if order.index(d.name) > i:
            return "ExecuteSlice", {"active_slice": d.name}
    return "QuestDocumenting", {}


def slice_implementing_next_state(slice_dir: Path) -> str:
    if implementer_done_signal(slice_dir, slice_dir, ""):
        return "PolishingReview"
    raise AdvanceValidationError(
        "Slice implementation is incomplete: create `implementation_done.md` "
        "before advancing.",
        reason="missing_implementation_done",
    )


def slice_polishing_review_next_state(slice_dir: Path) -> str:
    if slice_has_open_polishing_issues(slice_dir):
        return "PolishingFix"
    if implementation_review_done_signal(slice_dir):
        return "Completed"
    raise AdvanceValidationError(
        "Slice polishing review is incomplete: resolve open issues and create "
        "`implementation_accepted.md` before advancing.",
        reason="polishing_review_incomplete",
    )


def quest_documenting_next_state(
    *,
    repo_path: Path,
    quest_dir: Path,
    meta: QuestMeta,
    documenter_base_ref: str,
) -> str:
    quest_rel = quest_dir.resolve().relative_to(repo_path.resolve()).as_posix()
    project_rel = current_project_rel_for_quest(meta, quest_rel)
    docs_rel = f"{project_rel}/docs" if project_rel else "docs"
    if documenter_base_ref and docs_updated_for_quest(
        repo_path, documenter_base_ref, docs_rel
    ):
        return "Completed"
    raise AdvanceValidationError(
        "Quest documentation is incomplete: update project docs before advancing.",
        reason="docs_unchanged",
    )

"""Quest and slice machine nodes for the canonical recursive runner."""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from .. import quest_fs
from ..harness import create_harness
from ..quest_runner import (
    _get_slice_dir,
    git_rev_parse_head,
    perform_role_harness_sequence,
    role_thread_key,
    scaffold_slice_dir,
)
from .quest_v2_predicates import (
    physical_planning_next_state,
    prepare_next_slice_transition,
    quest_documenting_next_state,
    review_physical_plan_next_state,
    slice_implementing_next_state,
    slice_polishing_review_next_state,
)
from ..quest_thread import load_thread, resolve_or_create_thread_spec
from ..quest_types import QuestState, RecursiveSnapshot, SliceState
from .base_node import BaseNode
from .context import RunContext
from .machine import ConcreteStateMachine

if TYPE_CHECKING:
    from .protocols import StateMachine


class PrePlanningGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "PrePlanning"


class CompletedGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Completed"


class _ThreadLlmNode(BaseNode):
    m_role: str

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        assert ctx.captured_outputs_list is not None
        assert ctx.role_step_seq_box is not None
        if ctx.harness_steps_acc is not None:
            ctx.harness_steps_acc[0] += 1
        quest_dir = ctx.machine_root_dir
        qsi = quest_fs.read_quest_state(quest_dir)
        slice_dir: Path | None = None
        slice_state: SliceState | None = None
        if qsi.state == QuestState.ExecuteSlice and qsi.current_slice is not None:
            slice_dir = _get_slice_dir(quest_dir, qsi.current_slice)
            slice_state = quest_fs.read_slice_state(slice_dir).state
        meta = quest_fs.read_quest_meta(quest_dir)
        profiles = quest_fs.read_execution_config(quest_dir)
        harness_configs = quest_fs.read_harness_configs(quest_dir)
        profile = profiles[self.m_role]
        harness = create_harness(
            profile.harness, harness_configs.get(profile.harness.value)
        )
        quest_rel = quest_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        slice_rel: str | None = None
        if slice_dir is not None:
            slice_rel = slice_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        step_base = git_rev_parse_head(ctx.repo_root)
        thread_key = role_thread_key(self.m_role, slice_dir)
        thread_box: list = [
            load_thread(quest_dir, ctx.repo_root, self.m_role, registry_key=thread_key)
        ]
        assert ctx.conductor_repo_path is not None
        assert ctx.quest_docs_dir is not None
        assert ctx.role_step_seq_box is not None
        snum = qsi.current_slice if qsi.state == QuestState.ExecuteSlice else None

        def _create() -> object:
            return resolve_or_create_thread_spec(
                quest_dir,
                ctx.repo_root,
                self.m_role,
                harness,
                meta.quest_number,
                profile.model,
                profile.reasoning_effort,
                profile.idle_timeout_seconds,
                snum,
                registry_key=thread_key,
            )

        perform_role_harness_sequence(
            repo_path=ctx.repo_root,
            quest_dir=quest_dir,
            conductor_repo_path=ctx.conductor_repo_path,
            meta=meta,
            quest_docs_dir=ctx.quest_docs_dir,
            quest_state_info=qsi,
            slice_dir=slice_dir,
            slice_state=slice_state,
            profile=profile,
            harness=harness,
            role_name=self.m_role,
            thread_key=thread_key,
            quest_rel=quest_rel,
            slice_rel=slice_rel,
            step_base_commit=step_base,
            thread_box=thread_box,
            role_step_seq=ctx.role_step_seq_box,
            captured_outputs=ctx.captured_outputs_list,
            create_thread_if_missing=_create,
            event_bus=ctx.event_bus,
            experiment_id=ctx.experiment_id,
        )

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        raise NotImplementedError


class PhysicalPlanningNode(_ThreadLlmNode):
    m_role = "physical_planner"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return physical_planning_next_state(ctx.machine_root_dir)
        except Exception:
            return "PhysicalPlanning"


class ReviewPhysicalPlanNode(_ThreadLlmNode):
    m_role = "physical_plan_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return review_physical_plan_next_state(ctx.machine_root_dir)
        except Exception:
            return "ReviewPhysicalPlan"


class PrepareNextSliceNode(BaseNode):
    def __init__(self) -> None:
        self._picked = ""

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        nxt, tags = prepare_next_slice_transition(ctx.machine_root_dir)
        self._picked = tags.get("active_slice", "")
        return nxt

    def NodeTags(self, ctx: RunContext, machine: StateMachine) -> dict[str, str]:
        if self._picked:
            return {"active_slice": self._picked}
        return {}


class ExecuteActiveSliceNode(BaseNode):
    m_child_snapshot: object | None

    def __init__(self) -> None:
        self.m_child_snapshot = None

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        quest_dir = ctx.machine_root_dir
        top = quest_fs.read_quest_state(quest_dir)
        active = top.active_slice
        if not active:
            raise RuntimeError("ExecuteActiveSliceNode: missing active_slice")
        slice_dir = quest_dir / "slices" / active
        if not slice_dir.is_dir():
            raise RuntimeError(f"ExecuteActiveSliceNode: missing {slice_dir}")
        child = ctx.state_machine_loader.LoadStateMachine(slice_dir)
        assert isinstance(child, ConcreteStateMachine)
        self.m_child_snapshot = child.RunOneStep(ctx)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        if self.m_child_snapshot is None:
            raise RuntimeError("child snapshot missing")
        snap: RecursiveSnapshot = self.m_child_snapshot
        if snap.state_after == "Completed":
            return "PrepareNextSlice"
        return "ExecuteSlice"

    def PopChildRecursiveSnapshot(self) -> object | None:
        c = self.m_child_snapshot
        self.m_child_snapshot = None
        return c


class QuestDocumentingNode(_ThreadLlmNode):
    m_role = "documenter"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        box = ctx.documenter_base_ref_box
        if box is None:
            return "QuestDocumenting"
        ref = box[0]
        if not ref:
            return "QuestDocumenting"
        try:
            return quest_documenting_next_state(
                repo_path=ctx.repo_root,
                quest_dir=ctx.machine_root_dir,
                meta=quest_fs.read_quest_meta(ctx.machine_root_dir),
                documenter_base_ref=ref,
            )
        except Exception:
            return "QuestDocumenting"


class SliceSetupNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        scaffold_slice_dir(machine.StateMachineDir())

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Implementing"


class SliceImplementingNode(_ThreadLlmNode):
    m_role = "implementer"

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        self._step_base = git_rev_parse_head(ctx.repo_root)
        super().Execute(ctx, machine)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_implementing_next_state(machine.StateMachineDir())
        except Exception:
            return "Implementing"


class SlicePolishingReviewNode(_ThreadLlmNode):
    m_role = "polisher_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_polishing_review_next_state(machine.StateMachineDir())
        except Exception:
            return "PolishingReview"


class SlicePolishingFixNode(_ThreadLlmNode):
    m_role = "polisher"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "PolishingReview"


class SliceCompletedNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Completed"

"""Machine definitions and loader for the canonical recursive quest runner."""

from __future__ import annotations

from pathlib import Path

from .machine import ConcreteStateMachine
from .protocols import StateMachineDefinition
from .quest_v2_nodes import (
    CompletedGateNode,
    ExecuteActiveSliceNode,
    PhysicalPlanningNode,
    PrepareNextSliceNode,
    PrePlanningGateNode,
    QuestDocumentingNode,
    ReviewPhysicalPlanNode,
    SliceCompletedNode,
    SliceImplementingNode,
    SlicePolishingFixNode,
    SlicePolishingReviewNode,
    SliceSetupNode,
)


def build_quest_machine_definition() -> StateMachineDefinition:
    return StateMachineDefinition(
        machine_name="quest",
        node_map={
            "PrePlanning": PrePlanningGateNode,
            "PhysicalPlanning": PhysicalPlanningNode,
            "ReviewPhysicalPlan": ReviewPhysicalPlanNode,
            "PrepareNextSlice": PrepareNextSliceNode,
            "ExecuteSlice": ExecuteActiveSliceNode,
            "QuestDocumenting": QuestDocumentingNode,
            "Completed": CompletedGateNode,
        },
        terminal_states=("Completed",),
    )


def build_slice_machine_definition() -> StateMachineDefinition:
    return StateMachineDefinition(
        machine_name="slice",
        node_map={
            "SliceSetup": SliceSetupNode,
            "Implementing": SliceImplementingNode,
            "PolishingReview": SlicePolishingReviewNode,
            "PolishingFix": SlicePolishingFixNode,
            "Completed": SliceCompletedNode,
        },
        terminal_states=("Completed",),
    )


class QuestV2MachineLoader:
    def __init__(self, io: object) -> None:
        self.io = io
        self._quest_def = build_quest_machine_definition()
        self._slice_def = build_slice_machine_definition()

    def LoadStateMachine(self, state_machine_dir: Path) -> ConcreteStateMachine:
        p = state_machine_dir.resolve()
        qd = self.io.quest_dir.resolve()
        if p == qd:
            return ConcreteStateMachine(p, self._quest_def, self.io)
        return ConcreteStateMachine(p, self._slice_def, self.io)

    def LoadTopStateMachine(self, machine_root_dir: Path) -> ConcreteStateMachine:
        return self.LoadStateMachine(machine_root_dir)

